def P(parts, al=A.JUSTIFY, ind=0, hang=0, after=4, u=False):
    p=d.add_paragraph(); p.alignment=al
    if ind: p.paragraph_format.left_indent=Cm(ind)
    if hang: p.paragraph_format.first_line_indent=Cm(-hang)
    p.paragraph_format.space_after=Pt(after)
    if isinstance(parts,str): parts=[(parts,False)]
    for t,b in parts:
        r=p.add_run(t); r.bold=b; r.underline=u and b
    return p
